                .andExpect(jsonPath("$.roundFailed").value(0))
                .andExpect(jsonPath("$.roundSuccess").value(0));

        // 历史：1 条暂停（轮次1）+ 1 条恢复（新轮次2，含原因与 UTC 时刻）
        MvcResult history = mockMvc.perform(get("/api/releases/" + releaseId + "/history"))
