                return new PullResponse(null);
            }
            // 新任务拉取冻结守卫：命中生效窗口且例外不全即 422，本事务回滚不创建任务
            Long emergencyFreezeId = freezeService.guardTaskPull(device.model(), order.id(), deviceId,
                    grant, requestId);
